from collections import Counter

frequencies = {"low": 3, "lower": 2, "slow": 1}
pieces = {word: list(word) for word in frequencies}

for step in range(2):
    pairs = Counter()
    for word, tokens in pieces.items():
        for pair in zip(tokens, tokens[1:]):
            pairs[pair] += frequencies[word]
    best = max(pairs, key=pairs.get)  # First encountered wins ties.
    print(f"Merge {step + 1}: {best} count={pairs[best]}")
    for word, tokens in pieces.items():
        merged, i = [], 0
        while i < len(tokens):
            if tuple(tokens[i:i + 2]) == best:
                merged.append("".join(best))
                i += 2
            else:
                merged.append(tokens[i])
                i += 1
        pieces[word] = merged

for word, tokens in pieces.items():
    print(word, "->", tokens)
print("lower: 5 characters ->", len(pieces["lower"]), "pieces")

