import json

orders = {
    "A17": {"owner": "user-7", "refundable_cents": 1500},
    "B22": {"owner": "user-9", "refundable_cents": 2500},
}
authenticated_user = "user-7"  # Supplied by trusted authentication.

def check(raw):
    try:
        proposal = json.loads(raw)
    except json.JSONDecodeError:
        return "REJECT: invalid JSON"
    if not isinstance(proposal, dict) or set(proposal) != {"order_id", "amount_cents"}:
        return "REJECT: fields"
    if type(proposal["order_id"]) is not str or type(proposal["amount_cents"]) is not int:
        return "REJECT: types"
    order = orders.get(proposal["order_id"])
    if order is None or order["owner"] != authenticated_user:
        return "REJECT: not authorized"
    if not 0 < proposal["amount_cents"] <= order["refundable_cents"]:
        return "REJECT: amount"
    return "ELIGIBLE FOR APPROVAL: not executed"

proposals = [
    '{"order_id":"A17","amount_cents":1000}',
    '{"order_id":"A17","amount_cents":"1000"}',
    '{"order_id":"B22","amount_cents":1000}',
]
for number, raw in enumerate(proposals, 1):
    print(f"Proposal {number}: {check(raw)}")

