from math import exp, log

target_frequency = [0.75, 0.25, 0.0]
logits = [0.0, 0.0, 0.0]
learning_rate = 0.5

def probabilities(scores):
    weights = [exp(value - max(scores)) for value in scores]
    return [weight / sum(weights) for weight in weights]

for step in range(9):
    p = probabilities(logits)
    loss = -sum(f * log(prob) for f, prob in zip(target_frequency, p))
    if step in [0, 1, 4, 8]:
        print(f"step={step} loss={loss:.3f} p={[round(x, 3) for x in p]}")
    if step < 8:
        gradient = [prob - f for prob, f in zip(p, target_frequency)]
        logits = [
            value - learning_rate * grad
            for value, grad in zip(logits, gradient)
        ]

print("Most probable next token:", ["open", "closed", "locked"][p.index(max(p))])

