from math import sqrt

query = [1.0, 1.0]
passages = {"A": [1.0, 0.0], "B": [2.0, 2.0], "C": [-1.0, 1.0]}

def cosine(a, b):
    if len(a) != len(b):
        raise ValueError("Embedding dimensions differ.")
    norm_a = sqrt(sum(value * value for value in a))
    norm_b = sqrt(sum(value * value for value in b))
    if norm_a == 0 or norm_b == 0:
        raise ValueError("Cosine is undefined for a zero vector.")
    return sum(x * y for x, y in zip(a, b)) / (norm_a * norm_b)

ranking = sorted(
    ((name, cosine(query, vector)) for name, vector in passages.items()),
    key=lambda item: item[1], reverse=True,
)
for name, score in ranking:
    print(f"{name}: cosine={score:.3f}")
print("B scaled by ten:", f"{cosine(query, [20.0, 20.0]):.3f}")

