from collections import defaultdict

dense = ["B", "C", "A", "D"]
lexical = ["A", "B", "D", "C"]
scores = defaultdict(float)
for ranking in [dense, lexical]:
    for rank, document in enumerate(ranking, start=1):
        scores[document] += 1 / (60 + rank)

fused = sorted(scores, key=lambda d: (-scores[d], d))
reranker = {"A": 0.95, "B": 0.30, "C": 0.10, "D": 0.90}
reranked = sorted(fused, key=lambda d: (-reranker[d], d))
relevant = {"A", "D"}

def recall(ranking, k):
    return len(set(ranking[:k]) & relevant) / len(relevant)

print("Fused:", fused)
for document in fused:
    print(f"{document}: RRF={scores[document]:.5f}")
print("Reranked:", reranked)
print(f"Recall@2 before: {recall(fused, 2):.2f}")
print(f"Recall@2 after: {recall(reranked, 2):.2f}")

