evidence = {
    "S1": {
        "carry_days": {"value": 5, "qualifier": "up_to"},
        "expiry": {"value": "March 31", "qualifier": "exact"},
    }
}
claims = [
    ("C1", "S1", "carry_days", 5, "up_to"),
    ("C2", "S1", "carry_days", 5, "guaranteed"),
    ("C3", "S1", "expiry", "June 30", "exact"),
    ("C4", "S1", "office_closes", "Friday", "exact"),
]

def review(source_id, field, value, qualifier):
    fact = evidence.get(source_id, {}).get(field)
    if fact is None:
        return "UNSUPPORTED", "omit or seek evidence"
    if value != fact["value"]:
        return "CONTRADICTED", "correct against the source"
    if qualifier != fact["qualifier"]:
        return "PARTIAL", "preserve the qualification"
    return "SUPPORTED", "state with citation"

for claim_id, source_id, field, value, qualifier in claims:
    status, action = review(source_id, field, value, qualifier)
    print(f"{claim_id}: {status} -> {action}")
